// Placeholder dog avatars, so the picker is a working feature before the art
// exists.
//
// The ten real portraits are generated by hand from
// art/source/prompts-dog-avatars.txt and land at exactly the paths this script
// writes. Overwrite and nothing in the app changes — the manifest, the picker,
// the service worker precache and the stored `dog.photo` all already point
// here. That is the whole reason these exist rather than the picker rendering
// a different kind of tile until the art arrives: one code path, testable
// today, no swap-over to get wrong later.
//
// They are meant to look provisional. Each is the flat cream field the real
// art specifies, with a soft disc in a different hue, sized and placed exactly
// where a head has to sit — centred, about 70% of the frame, clear of the
// corners the circular mask discards. So they are wrong as pictures and right
// as geometry, which is the half the layout needs.
//
//   node scripts/make-avatar-placeholders.mjs

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { deflateSync } from 'node:zlib';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = resolve(root, 'img/avatars');

const SIZE = 400;

// #F6E6D0 — the field the prompts specify, and the splash field the app
// already paints. Every placeholder shares it, as the real ten must.
const FIELD = [246, 230, 208];

// One hue per slot so ten tiles in a grid are ten distinguishable things.
// Muted and warm, to stay inside the app's palette rather than turning the
// picker into a colour wheel.
const DISCS = [
  [ 45,  54,  58], // black lab      — charcoal
  [201, 154,  74], // golden         — gold
  [122,  92,  58], // shepherd       — tan
  [176, 143, 116], // frenchie       — fawn
  [214, 178, 138], // poodle         — apricot
  [162,  86,  52], // dachshund      — red
  [140, 110,  78], // beagle         — hound brown
  [ 74,  90,  96], // collie         — slate
  [186, 152, 118], // staffy         — light fawn
  [198, 186, 170], // shih tzu       — cream grey
];

// --- PNG ---------------------------------------------------------------------

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

const crc32 = (buf) => {
  let c = -1;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
};

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}

function writePng(path, size, pixel) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // truecolour
  const raw = Buffer.alloc(size * (size * 3 + 1));
  let p = 0;
  for (let y = 0; y < size; y++) {
    raw[p++] = 0; // filter: none
    for (let x = 0; x < size; x++) {
      const [r, g, b] = pixel(x, y);
      raw[p++] = r;
      raw[p++] = g;
      raw[p++] = b;
    }
  }
  writeFileSync(
    path,
    Buffer.concat([
      Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
      chunk('IHDR', ihdr),
      chunk('IDAT', deflateSync(raw, { level: 9 })),
      chunk('IEND', Buffer.alloc(0)),
    ])
  );
}

// --- the tile ----------------------------------------------------------------

const mix = (base, top, a) => base.map((c, i) => Math.round(c + (top[i] - c) * a));

/**
 * Coverage of one pixel by a disc, antialiased across a one-pixel band.
 *
 * Hard-edged circles at 400² look fine and then crawl when the browser scales
 * them into a 96px slot, which is the size this is actually seen at.
 */
const discCoverage = (x, y, cx, cy, r) => {
  const d = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
  return Math.max(0, Math.min(1, r - d + 0.5));
};

mkdirSync(outDir, { recursive: true });

DISCS.forEach((disc, i) => {
  const n = String(i + 1).padStart(2, '0');
  const cx = SIZE / 2;
  const cy = SIZE / 2;
  // 70% of the frame, matching the head size the prompts ask for, which keeps
  // the whole thing inside the 80% circle the avatar mask leaves visible.
  const r = SIZE * 0.35;

  writePng(resolve(outDir, `dog-${n}.png`), SIZE, (x, y) => {
    const a = discCoverage(x, y, cx, cy, r);
    return a <= 0 ? FIELD : mix(FIELD, disc, a);
  });
});

console.log(`Wrote ${DISCS.length} placeholder avatars to img/avatars/`);
console.log('Replace with the real art at the same paths — no code change needed.');
